class Solution {
    private void nextPermutation(char[] arr) {
        int n = arr.length, i = n - 2;
        while (i >= 0 && arr[i] >= arr[i + 1]) i--;
        if (i >= 0) {
            int j = n - 1;
            while (arr[j] <= arr[i]) j--;
            char t = arr[i]; arr[i] = arr[j]; arr[j] = t;
        }
        int l = i + 1, r = n - 1;
        while (l < r) {
            char t = arr[l]; arr[l] = arr[r]; arr[r] = t;
            l++; r--;
        }
    }

    public int getMinSwaps(String num, int k) {
        char[] target = num.toCharArray();
        for (int step = 0; step < k; ++step) {
            nextPermutation(target);
        }

        char[] orig = num.toCharArray();
        int ans = 0, n = orig.length;
        for (int i = 0; i < n; ++i) {
            if (orig[i] != target[i]) {
                int j = i;
                while (orig[j] != target[i]) j++;
                while (j > i) {
                    char t = orig[j]; orig[j] = orig[j - 1]; orig[j - 1] = t;
                    ans++;
                    j--;
                }
            }
        }
        return ans;
    }
}

