var getMinSwaps = function(num, k) {
    const target = num.split('');
    const n = target.length;

    function nextPerm(arr) {
        let i = n - 2;
        while (i >= 0 && arr[i] >= arr[i + 1]) i--;
        if (i >= 0) {
            let j = n - 1;
            while (arr[j] <= arr[i]) j--;
            [arr[i], arr[j]] = [arr[j], arr[i]];
        }
        let l = i + 1, r = n - 1;
        while (l < r) {
            [arr[l], arr[r]] = [arr[r], arr[l]];
            l++; r--;
        }
    }

    for (let step = 0; step < k; ++step) {
        nextPerm(target);
    }

    const orig = num.split('');
    let ans = 0;
    for (let i = 0; i < n; ++i) {
        if (orig[i] !== target[i]) {
            let j = i;
            while (orig[j] !== target[i]) j++;
            while (j > i) {
                [orig[j], orig[j - 1]] = [orig[j - 1], orig[j]];
                ans++;
                j--;
            }
        }
    }
    return ans;
};
